<?php
// Reviewed registration extensions. Existing posting ledger remains authoritative.
function rd_form_input($input){$input['payload_used']=false;if(!empty($input['rd_payload'])){$payload=json_decode((string)$input['rd_payload'],true,16,JSON_THROW_ON_ERROR);if(!is_array($payload))throw new Exception('Invalid selection payload.');foreach(['selected_rows','orders','dispatch_dates'] as $key){if(!isset($payload[$key])||!is_array($payload[$key])||count($payload[$key])>10000)throw new Exception('Invalid or excessive selection.');$input[$key]=$payload[$key];}$input['payload_used']=true;}return $input;}
function rd_batch($id,$revision=null){om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[(int)$id])->fetch();$b=om_upload($id);om_owner($b);if($b['kind']!=='Register')throw new Exception('Use an unconfirmed registration upload.');if($revision!==null&&(int)$b['revision']!==(int)$revision)throw new Exception('Upload changed. Review again.');return $b;}
function rd_review_dates($lines,$order,$meta,$postingDate,$batch){$d=om_date_details($lines,$order,$meta);if(!empty($meta['late_registration'])){$actual=$meta['actual_dispatch_dates'][hash('sha256',(string)($lines[0]['order']??''))]??'';$d['fulfillment_date']=$actual;$d['posting_date']=$postingDate?:$actual;$d['registration_recorded_at']=$batch['created_at'];$d['posting_basis']=$d['shipping_dates']?'Platform shipping timestamp; reviewed late dispatch':'Manually verified actual dispatch date; reason retained';}return $d;}
function rd_identity($b,$line){$sku=sm_value($line,$b['platform']);if($sku===''&&empty($line['external']))throw new Exception('Bulk correction needs a SKU identity. Correct blank identities individually.');return $line;}
function rd_bulk_plan($id,$revision,$rowNo,$input){om_require();$b=rd_batch($id,$revision);$source=null;foreach($b['rows'] as $line)if((int)$line['row']===(int)$rowNo)$source=$line;if(!$source)throw new Exception('Source row not found.');rd_identity($b,$source);$components=bundle_components_validate($input['components']??[]);$matches=[];
 foreach($b['rows'] as $line){if(!sm_identity_match($b['platform'],$source,$line)||oi_exclusion($b,$line['order'])||om_find($b['platform'],$b['shop'],$line['order']))continue;$before=[];$error='';try{$before=om_components($b['platform'],$b['shop'],$line);}catch(Throwable $e){$error=$e->getMessage();}$matches[]=['row'=>(int)$line['row'],'order'=>$line['order'],'qty'=>(int)$line['qty'],'before'=>$before,'previous_issue'=>$error];}
 if(!$matches)throw new Exception('No eligible matching source rows. Registered and removed orders are excluded.');return ['id'=>(int)$id,'revision'=>(int)$b['revision'],'row_no'=>(int)$rowNo,'platform'=>$b['platform'],'shop'=>$b['shop'],'sku'=>sm_value($source,$b['platform']),'variation'=>$source['variation'],'components'=>$components,'matches'=>$matches,'save_mapping'=>!empty($input['save_mapping']),'reason'=>process_reason($input['reason']??'Bulk correction of verified SKU mapping')];
}
function rd_bulk_apply($plan,$selected){om_require();if(!is_array($selected)||!$selected)throw new Exception('Select source rows to correct.');$selected=array_values(array_unique(array_map('intval',$selected)));return process_transaction(function()use($plan,$selected){$fresh=rd_bulk_plan($plan['id'],$plan['revision'],$plan['row_no'],$plan);if($fresh!==$plan)throw new Exception('Mapping or source changed. Preview again.');$eligible=array_column($plan['matches'],'row');if(array_diff($selected,$eligible))throw new Exception('An ineligible source row was selected.');$b=om_upload($plan['id']);$changes=[];$remember=[];foreach($b['rows'] as &$line){if(!in_array((int)$line['row'],$selected,true))continue;$before=null;foreach($plan['matches'] as $m)if($m['row']===(int)$line['row'])$before=$m;$line['components']=$plan['components'];$line['mapping_is_manual']=true;$remember[]=$line;$changes[]=['order'=>$line['order'],'row'=>$line['row'],'quantity'=>$line['qty'],'before'=>$before['before'],'after'=>$line['components']];}unset($line);if($plan['save_mapping'])sm_remember_confirmed($b['platform'],$b['shop'],$remember);om_query('UPDATE om_uploads SET rows_json=?,revision=revision+1 WHERE id=?',[json_encode($b['rows']),$b['id']]);om_event(null,$b['id'],'Bulk mapping corrected',['reason'=>$plan['reason'],'sku'=>$plan['sku'],'variation'=>$plan['variation'],'changes'=>$changes,'mapping_saved'=>$plan['save_mapping'],'stock_changed'=>false]);audit('Bulk mapping corrected','Order Monitoring',(string)$b['id'],count($changes).' source rows; stock effect 0; '.$plan['reason']);return count($changes);});}
function rd_late_date($lines,$meta){$dates=[];$created=[];foreach(om_source_date_lines($lines) as $line){if(!empty($line['date_errors']))throw new Exception(implode(' · ',$line['date_errors']));if(empty($line['created']))throw new Exception('Missing order creation date.');$created[]=substr($line['created'],0,10);if(!empty($line['ship_at'])){$dates[]=substr($line['ship_at'],0,10);if($line['ship_at']<$line['created'])throw new Exception('Shipping timestamp predates order creation.');}if(!empty($line['delivered_at'])&&!empty($line['ship_at'])&&$line['delivered_at']<$line['ship_at'])throw new Exception('Delivery predates dispatch.');foreach(['ship_at','delivered_at','created'] as $field)if(!empty($line[$field])&&$line[$field]>date('Y-m-d H:i:s'))throw new Exception('Source event timestamp is in the future.');}
 $no=(string)$lines[0]['order'];$actual=process_date($meta['actual_dispatch_dates'][hash('sha256',$no)]??'');$dates=array_unique($dates);if(count($dates)>1)throw new Exception('Conflicting dispatch dates across item lines. Review individually.');if($dates&&reset($dates)!==$actual)throw new Exception('Actual dispatch date conflicts with the platform shipping date.');if($actual<max($created)||$actual>date('Y-m-d'))throw new Exception('Actual dispatch must be between order creation and today.');require_open_inventory_date($actual);return $actual;}
function rd_late_history_guard($b,$no,$lines,$totals,$date,$used){
 if(om_query("SELECT COUNT(*) FROM outflows WHERE platform=? AND order_id=? AND type='Order'",[$b['platform'],$no])->fetchColumn())throw new Exception('An original outflow already exists. Link the recorded dispatch; do not deduct again.');
 foreach($totals as $pid=>$qty){check_platform_alignment($pid);$begin=om_query('SELECT DATE(updated_at) FROM beginning_balances WHERE product_id=?',[$pid])->fetchColumn();if($begin&&$begin>$date)throw new Exception('Dispatch predates the recorded Beginning Balance. Admin must reconcile the starting cutoff; no automatic deduction.');
 $count=om_query("SELECT b.batch_ref FROM inventory_count_batches b JOIN inventory_count_lines l ON l.batch_id=b.id WHERE l.product_id=? AND b.count_date>=? AND b.status NOT IN ('Cancelled','Reversed') LIMIT 1",[$pid,$date])->fetchColumn();if($count)throw new Exception('An inventory count covers this dispatch date: '.$count.'. Admin must review its cutoff first.');
 $required=(int)$qty+(int)($used[$pid]??0);$days=[$date];foreach(inventory_ledger($pid) as $e)if($e['date']>=$date)$days[]=$e['date'];foreach(om_query('SELECT DISTINCT txn_date FROM stock_events WHERE product_id=? AND platform=? AND txn_date>=?',[$pid,$b['platform'],$date]) as $e)$days[]=$e['txn_date'];foreach(array_unique($days) as $day){if(inventory_balance_at($pid,$day)['sellable']<$required||report_platform_balance($pid,$b['platform'],$day)<$required)throw new Exception('Backdated dispatch would create a negative balance on '.$day.'. Reconcile the source stock and allocation first.');}
 }
}
function rd_late_validate($b,$lines,$totals,$used){if(empty($b['meta']['late_dispatch_ack'])||empty($b['meta']['not_previously_deducted_ack']))throw new Exception('Verify dispatch and opening-balance / prior-deduction acknowledgement.');process_reason($b['meta']['reason']??'');$statuses=array_unique(array_column($lines,'status'));if(count($statuses)!==1||!in_array(reset($statuses),['Shipped','Delivered','Completed'],true)||array_filter($lines,fn($l)=>!empty($l['aftersales'])))throw new Exception('Late dispatch accepts only verified Shipped, Delivered or Completed orders without pending after-sales.');$date=rd_late_date($lines,$b['meta']);rd_late_history_guard($b,(string)$lines[0]['order'],$lines,$totals,$date,$used);return $date;}
function rd_late_stage($id,$revision,$orders,$dates,$reason,$ack){om_require();if(!$ack)throw new Exception('Confirm actual dispatch and that stock was not previously deducted or included in a starting balance.');if(!is_array($orders)||!$orders||count($orders)>5000||!is_array($dates))throw new Exception('Select orders and their actual dispatch dates.');$orders=array_values(array_unique(array_map('strval',$orders)));return process_transaction(function()use($id,$revision,$orders,$dates,$reason){$b=rd_batch($id,$revision);if(!empty($b['meta']['late_registration']))throw new Exception('This is already a late-dispatch review.');$groups=[];foreach($b['rows'] as $line)if(in_array((string)$line['order'],$orders,true))$groups[(string)$line['order']][]=$line;if(count($groups)!==count($orders))throw new Exception('Selected order is not in this upload.');$meta=$b['meta'];unset($meta['excluded_orders']);$meta['late_registration']=true;$meta['late_dispatch_ack']=true;$meta['not_previously_deducted_ack']=true;$meta['reason']=process_reason($reason);$meta['parent_upload_id']=(int)$id;$meta['actual_dispatch_dates']=[];$sorted=[];
 foreach($groups as $no=>$lines){if(oi_exclusion($b,(string)$no))throw new Exception('Restore removed orders before selecting them.');if(om_find($b['platform'],$b['shop'],(string)$no))throw new Exception('An order is already registered. Refresh; use Update Status for existing orders.');$statuses=array_unique(array_column($lines,'status'));if(count($statuses)!==1||!in_array(reset($statuses),['Shipped','Delivered','Completed'],true))throw new Exception('Select only unregistered dispatched orders.');$key=hash('sha256',(string)$no);$meta['actual_dispatch_dates'][$key]=process_date($dates[$key]??'');$date=rd_late_date($lines,$meta);$sorted[]=['date'=>$date,'order'=>(string)$no,'lines'=>$lines];}
 usort($sorted,fn($a,$b)=>[$a['date'],$a['order']]<=>[$b['date'],$b['order']]);$rows=[];foreach($sorted as $g)$rows=array_merge($rows,$g['lines']);$meta['late_review_key']=hash('sha256',json_encode([$id,$revision,$rows,$meta['actual_dispatch_dates'],$meta['reason']]));foreach(om_query("SELECT id,meta_json FROM om_uploads WHERE kind='Register' AND platform=? AND shop=? AND created_by=? AND status='Review'",[$b['platform'],$b['shop'],current_user()['id']]) as $open){$openMeta=json_decode($open['meta_json'],true)?:[];if(($openMeta['late_review_key']??'')===$meta['late_review_key'])return (int)$open['id'];}$child=om_stage_rows('Register',$meta,$rows,$b['filename'].' · late-dispatch review',$b['stored_path'],$b['file_hash']);om_event(null,$id,'Late dispatch review created',['review_upload_id'=>$child,'orders'=>$orders,'reason'=>$meta['reason'],'stock_changed'=>false]);return $child;
 });}
function rd_post_dispatch($b,$r,$oid,$late=false){$date=$r['posting_date'];if(!$date)throw new Exception('Reopen review: posting date has not been validated.');require_open_inventory_date($date);$id=$b['id'];$meta=['order_monitor_upload'=>$id,'order_no'=>$r['order'],'dispatch_confirmed'=>true,'source_snapshot'=>$b['meta']['snapshot']??null,'late_registration'=>$late,'actual_dispatch_date'=>$date,'parent_upload_id'=>$b['meta']['parent_upload_id']??null];
 om_query("INSERT INTO import_batches(platform,import_type,filename,stored_path,status,rows_read,units,imported_count,result_json,user_id) VALUES(?,'Orders',?,?,'Complete',?,?,1,?,?)",[$b['platform'],$b['filename'],$b['stored_path'],count($r['lines']),array_sum($r['totals']),json_encode($meta),current_user()['id']]);$batch=(int)db()->lastInsertId();$effects=[];foreach($r['totals'] as $pid=>$qty){check_platform_alignment($pid);$before=stock_row($pid);$reserved=om_reserved($pid);om_query('INSERT INTO outflows(txn_date,platform,order_id,product_id,source_item,qty,type,import_batch_id,dedupe_key,remarks,user_id) VALUES(?,?,?,?,?,?,\'Order\',?,?,?,?)',[$date,$b['platform'],$r['order'],$pid,'Order monitor #'.$oid,$qty,$batch,hash('sha256','om|'.$oid.'|'.$pid),'Shop '.$b['shop'].'; '.($late?'late registration / dispatch':'status upload').' #'.$id.($late?'; actual dispatch '.$date.'; encoded '.date('Y-m-d H:i:s').'; '.$b['meta']['reason']:''),current_user()['id']]);$outflow=(int)db()->lastInsertId();om_query('INSERT INTO om_postings(order_id,outflow_id) VALUES(?,?)',[$oid,$outflow]);change_platform_stock($b['platform'],$pid,-$qty,$r['order'],$date);if(!$late)om_reserve_change($oid,$pid,-$qty,'Consumed by dispatch');check_platform_alignment($pid);$effects[]=['product'=>$before['name'],'sku'=>$before['master_sku'],'available_before'=>$before['current']-$reserved,'available_after'=>stock_row($pid)['current']-om_reserved($pid),'physical_before'=>$before['physical'],'physical_after'=>stock_row($pid)['physical'],'reserved_before'=>$reserved,'reserved_after'=>om_reserved($pid),'outflow_id'=>$outflow];}om_query("UPDATE om_orders SET posting='Posted' WHERE id=?",[$oid]);return $effects;}
function rd_late_finish($b,$r,$oid){$effects=rd_post_dispatch($b,$r,$oid,true);$status=$r['status'];$monitor=in_array($status,['Delivered','Completed'],true)?'Resolved':'Needs Follow-up';$ships=om_date_details($r['lines'])['shipping_dates'];$delivered=om_date_details($r['lines'])['delivered_dates'];$seen=$delivered?max($delivered):($ships?max($ships):($r['posting_date']===date('Y-m-d')?date('Y-m-d H:i:s'):$r['posting_date'].' 23:59:59'));om_query('UPDATE om_orders SET platform_status=?,monitoring=?,fulfillment_date=?,last_seen_at=?,last_snapshot=?,status_changed_at=?,revision=revision+1 WHERE id=?',[$status,$monitor,$r['posting_date'],$seen,$seen,$seen,$oid]);$o=om_order($oid);oa_record_report($o,$status,$seen,$b['id']);om_event($oid,$b['id'],'Late dispatch recorded',['source'=>'Late-recorded dispatch review','reason'=>$b['meta']['reason'],'actual_event_date'=>$r['posting_date'],'system_encoding_time'=>date('Y-m-d H:i:s'),'parent_upload_id'=>$b['meta']['parent_upload_id'],'effects'=>$effects,'source_lines'=>$r['lines'],'after_status'=>$status,'posting'=>'Posted','not_previously_deducted_ack'=>true]);}
function rd_process_report($input){if(!access_report_allowed('registration_process'))throw new Exception('Your role cannot access detailed correction history.');$platform=$input['platform']??'';if($platform!=='')stock_platform($platform);$rows=[];foreach(om_query("SELECT e.*,b.platform,b.filename,u.name actor FROM om_events e JOIN om_uploads b ON b.id=e.upload_id LEFT JOIN users u ON u.id=e.user_id WHERE e.event_type IN ('Bulk mapping corrected','Late dispatch recorded','Late dispatch review created') ORDER BY e.id DESC") as $e){if($platform!==''&&$e['platform']!==$platform)continue;$d=json_decode($e['details_json'],true)?:[];if($e['event_type']==='Bulk mapping corrected')foreach($d['changes']??[] as $change)$rows[]=[$e['created_at'],$e['platform'],$e['event_type'],$e['upload_id'],$change['order'],$change['row'],$change['quantity'],rd_component_label($change['before']),rd_component_label($change['after']),'',0,$e['actor'],$d['reason']??'',$e['filename']];else{$o=$e['order_id']?om_order($e['order_id']):null;$qty=0;foreach($d['effects']??[] as $effect)$qty+=(int)$effect['physical_before']-(int)$effect['physical_after'];$rows[]=[$e['created_at'],$e['platform'],$e['event_type'],$e['upload_id'],$o['order_no']??implode(', ',$d['orders']??[]),'','', '', '',$d['actual_event_date']??'',-$qty,$e['actor'],$d['reason']??'',$e['filename']];}}
 return ['title'=>'Registration Corrections and Late Dispatch History','headers'=>['Recorded At','Platform','Action','Upload','Order ID','Source Row','Uploaded Qty','Previous Mapping','Corrected Mapping','Actual Dispatch Date','Physical Stock Change','User','Reason','Source File'],'rows'=>$rows];}
function rd_component_label($components){$out=[];foreach($components??[] as $c){$p=om_query('SELECT master_sku,name FROM products WHERE id=?',[$c['product_id']])->fetch()?:[];$out[]=($p['master_sku']??'#'.$c['product_id']).' · '.($p['name']??'Product').' x '.(int)$c['per_bundle'];}return implode('; ',$out);}
function rd_inventory_report($input){$f=report_filters($input);$r=rd_process_report($f);$r['rows']=array_values(array_filter($r['rows'],fn($row)=>substr($row[0],0,10)>=$f['from']&&substr($row[0],0,10)<=$f['to']&&(!$f['q']||str_contains(norm(implode(' ',$row)),norm($f['q'])))));$links=array_map(fn($row)=>'index.php?page=outflow&upload_id='.(int)$row[3],$r['rows']);return $r+['filters'=>$f,'links'=>$links,'summary'=>[],'notes'=>['Date filters use encoding / correction date. Actual dispatch date is shown separately. Stock Movements and stock balance reports use the actual dispatch date. Bulk mapping correction has zero physical stock effect.'],'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name']];}
function rd_mapping_history($batch,$oid,$no){$ids=[(int)$batch['id']];if(!empty($batch['meta']['parent_upload_id']))$ids[]=(int)$batch['meta']['parent_upload_id'];foreach($ids as $id)foreach(om_query("SELECT id,details_json,created_at FROM om_events WHERE upload_id=? AND event_type='Bulk mapping corrected' AND order_id IS NULL ORDER BY id",[$id]) as $event){$d=json_decode($event['details_json'],true)?:[];foreach($d['changes']??[] as $change)if((string)$change['order']===(string)$no)om_event($oid,$batch['id'],'Bulk mapping applied to order',['reason'=>$d['reason'],'source'=>'Registration review · upload #'.$id.' · source row '.$change['row'],'components'=>$change['after'],'previous_mapping'=>rd_component_label($change['before']),'original_correction_at'=>$event['created_at'],'stock_changed'=>false]);}}
